// A stand-in for a real email client (SMTP, SES, SendGrid...).
// Do NOT edit this file. It deliberately fails the way a real network client
// would when a unit test reaches it: slowly, flakily, or not at all.
export class EmailSender {
  async send(to: string, body: string): Promise<void> {
    throw new Error(
      `SMTP unreachable: a unit test just tried to email ${to} for real ("${body}")`,
    );
  }
}
